import { Dispatch, SetStateAction } from "react";
import Modal from "./Modal";

export type ButtonType = "Create" | "Join" | "Next";

interface ButtonProps {
  type: ButtonType;
  isOpen?: boolean;
  setIsOpenModal?: Dispatch<SetStateAction<boolean>>;
}

export default function Button({ type, isOpen, setIsOpenModal }: ButtonProps) {
  return (
    <>
      <button
        onClick={() => setIsOpenModal !== undefined && setIsOpenModal(true)}
        className={`p-2 mt-5 w-50 rounded-[10px] cursor-pointer 
          ${type === "Create" || type === "Next" ? "bg-white text-black" : "border border-gray-500"}`}
      >
        {(type === "Create" && "Создать комнату") ||
          (type === "Join" && "Войти по коду") ||
          (type === "Next" && "Продолжить")}
      </button>
      {/* {setIsOpenModal !== undefined && isOpen !== undefined && (
        <>
          {type === "Create" && (
            <Modal
              isOpen={isOpen}
              setIsOpen={setIsOpenModal}
              buttonType={`Create`}
            />
          )}
          {type === "Join" && (
            <Modal
              isOpen={isOpen}
              setIsOpen={setIsOpenModal}
              buttonType="Join"
            />
          )}
        </>
      )} */}
    </>
  );
}
